        ('Q01', 'LINGUAGENS', 'Língua Portuguesa', 'Interpretação de Texto', $text$Uma prefeitura anuncia: “A cidade ganhou tempo: o atendimento agora é digital”. Em uma reportagem, uma moradora relata que gastou duas manhãs procurando um local com internet para solicitar o serviço. Ao aproximar os dois textos, qual conclusão considera adequadamente a relação entre inovação e acesso?$text$, $text$O anúncio generaliza uma vantagem que depende de condições materiais desigualmente distribuídas. O depoimento não nega a possibilidade de rapidez, mas limita seu alcance social.$text$, 'A', $text$A economia de tempo anunciada depende das condições de acesso dos usuários.$text$, $text$A experiência individual comprova que nenhum serviço digital pode ser eficiente.$text$, $text$O anúncio e o depoimento avaliam etapas sem relação com o mesmo serviço.$text$, $text$A moradora rejeita a inovação por preferir necessariamente o atendimento presencial.$text$, $text$A informatização iguala o tempo gasto por todos ao eliminar o deslocamento até a prefeitura.$text$),
        ('Q02', 'LINGUAGENS', 'Língua Portuguesa', 'Gêneros Textuais', $text$Um jornal publica uma reportagem sobre desperdício de alimentos. No dia seguinte, uma leitora escreve à seção de cartas: “Os números são relevantes, mas faltou ouvir as cooperativas que recolhem os excedentes. Sem elas, o problema parece responsabilidade exclusiva das famílias”. Qual é a função da carta nessa situação comunicativa?$text$, $text$A leitora retoma uma publicação, avalia seu recorte e solicita a inclusão de uma perspectiva ausente. Assim, participa criticamente do debate público promovido pelo jornal.$text$, 'B', $text$Substituir a reportagem por um relato técnico sobre coleta seletiva.$text$, $text$Reavaliar o enquadramento da reportagem e ampliar as vozes do debate.$text$, $text$Confirmar que os dados publicados são necessariamente falsos.$text$, $text$Estabelecer regras obrigatórias para a atuação das cooperativas.$text$, $text$Transformar a seção de leitores em publicidade de serviços de coleta.$text$),
        ('Q03', 'LINGUAGENS', 'Língua Portuguesa', 'Coesão e Coerência', $text$Leia o trecho autoral: “O aplicativo promete aproximar vizinhos. Para isso, organiza trocas de objetos e serviços. Essa proximidade, porém, termina onde começa a falta de conexão”. Na construção do argumento, a expressão “essa proximidade” e o conectivo “porém” atuam, respectivamente, para$text$, $text$A expressão retoma a aproximação entre vizinhos e a transforma em objeto de avaliação. O conectivo introduz uma restrição à promessa, relacionada à exclusão de quem não tem conexão.$text$, 'C', $text$anunciar um exemplo e explicar sua causa.$text$, $text$substituir o aplicativo e confirmar sua eficiência universal.$text$, $text$retomar uma ideia anterior e restringir seu alcance.$text$, $text$recuperar apenas os objetos e estabelecer uma sequência temporal.$text$, $text$antecipar uma conclusão e acrescentar uma vantagem equivalente.$text$),
        ('Q04', 'LINGUAGENS', 'Língua Portuguesa', 'Funções da Linguagem', $text$Uma campanha contra o descarte de lixo em rios apresenta a frase autoral “O rio não tem lixeira. E a sua rua também não”. Não há imagem de pessoas nem ordem no imperativo. Mesmo assim, predomina uma intenção apelativa porque o texto$text$, $text$A função apelativa depende da finalidade de influenciar o interlocutor, não apenas da presença de verbos no imperativo. A associação entre rio e rua questiona o descarte no espaço público.$text$, 'D', $text$explica o significado técnico da palavra lixeira.$text$, $text$informa resultados de uma pesquisa sobre a composição dos rios.$text$, $text$centraliza a mensagem na experiência íntima do autor.$text$, $text$busca orientar a conduta do leitor por uma associação entre espaços cotidianos.$text$, $text$verifica se o canal de comunicação está funcionando.$text$),
        ('Q05', 'LINGUAGENS', 'Língua Portuguesa', 'Variação Linguística', $text$Uma estudante usa expressões de sua comunidade em um documentário e adota registro formal ao redigir um requerimento. Um colega afirma que ela “aprendeu a falar corretamente” apenas no segundo caso. Que análise contesta essa afirmação sem desconsiderar as exigências dos gêneros?$text$, $text$A competência comunicativa inclui ajustar o registro ao contexto. A adequação do requerimento não transforma a variedade usada no documentário em uma forma inferior da língua.$text$, 'E', $text$A variedade comunitária deve ser usada em qualquer documento para impedir discriminação.$text$, $text$O domínio de um registro exige abandonar os demais em todas as interações.$text$, $text$O registro formal é uma língua independente das variedades orais.$text$, $text$A legitimidade de uma variedade depende apenas do número de seus falantes.$text$, $text$Os registros atendem a situações distintas, e o formal não invalida a variedade comunitária.$text$),
        ('Q06', 'LINGUAGENS', 'Literatura', 'Interpretação de Textos Literários', $text$No fragmento autoral “A casa foi vendida em março. Minha mãe ainda a abre quando conta histórias”, o segundo período desloca o sentido do primeiro ao representar a casa como$text$, $text$A venda encerra a posse material, mas a expressão “a abre” atribui à narrativa o poder de reativar lembranças. A casa permanece como espaço afetivo reconstruído pela memória.$text$, 'A', $text$um espaço afetivo que a memória torna novamente acessível.$text$, $text$um bem cuja transferência de propriedade não foi concluída.$text$, $text$um imóvel visitado fisicamente durante cada relato.$text$, $text$uma prova de que a narradora confunde as datas da venda.$text$, $text$um patrimônio cujo valor depende exclusivamente do preço de mercado.$text$),
        ('Q07', 'LINGUAGENS', 'Literatura', 'Modernismo', $text$Em um projeto literário, estudantes escrevem poemas com fala cotidiana, cenas de ônibus e rupturas na pontuação. A professora relaciona a experiência a uma vertente do modernismo brasileiro. Essa aproximação se sustenta na$text$, $text$A incorporação do cotidiano e da oralidade amplia os materiais da poesia e questiona convenções formais. Não implica ausência de elaboração nem rejeição de toda tradição.$text$, 'B', $text$adoção obrigatória da métrica clássica como garantia de nacionalidade.$text$, $text$experimentação formal associada à valorização de experiências comuns.$text$, $text$exclusão de conflitos urbanos em favor de paisagens idealizadas.$text$, $text$substituição do trabalho artístico pela transcrição neutra da fala.$text$, $text$recusa de qualquer diálogo com produções literárias anteriores.$text$),
        ('Q08', 'LINGUAGENS', 'Língua Inglesa', 'Interpretação de Texto', $text$Um cartaz de uma biblioteca comunitária diz: “Borrow a book. Bring a story back. Your voice belongs on these shelves, too.” Ao combinar empréstimo e participação, a mensagem sugere que a biblioteca pretende$text$, $text$“Borrow” remete ao empréstimo; “your voice” e “too” incluem o leitor na produção de histórias. O convite amplia o papel da biblioteca para a circulação de experiências da comunidade.$text$, 'C', $text$exigir uma obra publicada como pagamento por cada empréstimo.$text$, $text$reservar as estantes a autores que já tenham reconhecimento comercial.$text$, $text$acolher leitores também como produtores de narrativas da comunidade.$text$, $text$substituir a leitura silenciosa por apresentações obrigatórias.$text$, $text$limitar o acervo a relatos escritos originalmente em inglês.$text$),
        ('Q09', 'LINGUAGENS', 'Língua Espanhola', 'Vocabulário em Contexto', $text$Em uma campanha de mobilidade lê-se: “Compartir el viaje no basta: hace falta que el transporte llegue también a quienes viven lejos”. No contexto, a relação entre “no basta” e “hace falta” constrói uma$text$, $text$A primeira expressão apresenta o compartilhamento como insuficiente; a segunda aponta a necessidade de cobertura territorial. A campanha acrescenta uma condição para uma mobilidade inclusiva.$text$, 'D', $text$negação de qualquer benefício do compartilhamento de viagens.$text$, $text$comparação entre dois meios de transporte com custos idênticos.$text$, $text$explicação de que a distância deixou de afetar a mobilidade.$text$, $text$ressalva à suficiência de uma medida e indicação de outra necessidade.$text$, $text$oposição entre viajar acompanhado e preservar a privacidade.$text$),
        ('Q10', 'LINGUAGENS', 'Artes', 'Arte Contemporânea', $text$Uma artista instala, em uma praça, moldes de bancos que não permitem sentar. Ao lado, registra depoimentos de moradores expulsos de espaços de convivência por reformas urbanas. A articulação entre objeto e depoimentos produz sentido ao$text$, $text$A forma reconhecível do banco cria expectativa de acolhimento, frustrada pela impossibilidade de uso. Essa experiência se relaciona aos relatos de exclusão e converte o objeto em crítica urbana.$text$, 'E', $text$restaurar a função utilitária dos bancos retirados pela reforma.$text$, $text$demonstrar que o valor artístico depende da durabilidade dos materiais.$text$, $text$reduzir os depoimentos a instruções para utilizar a instalação.$text$, $text$separar a experiência estética das disputas pelo espaço público.$text$, $text$transformar a impossibilidade de uso em experiência crítica da exclusão urbana.$text$),
        ('Q11', 'LINGUAGENS', 'Língua Portuguesa', 'Semântica', $text$Uma rede de lojas divulga: “Até 70% de desconto em produtos selecionados”. Um consumidor afirma que todos os produtos deveriam custar 30% do preço original. Qual elemento linguístico impede essa interpretação?$text$, $text$“Até” estabelece um limite máximo, sem garantir esse percentual a todos os itens. “Selecionados” restringe o conjunto abrangido. A leitura do consumidor ignora ambas as limitações.$text$, 'A', $text$A combinação de um limite máximo com uma restrição do conjunto de produtos.$text$, $text$O uso de uma porcentagem, que sempre expressa uma média de preços.$text$, $text$A expressão “de desconto”, que indica acréscimo sobre o preço anunciado.$text$, $text$O plural “produtos”, que inclui obrigatoriamente o estoque inteiro.$text$, $text$O número 70, que informa o percentual mínimo de abatimento.$text$),
        ('Q12', 'LINGUAGENS', 'Língua Portuguesa', 'Figuras de Linguagem', $text$Leia os versos autorais: “Na reunião, todos tinham voz. Na decisão, só o microfone do chefe funcionava”. A crítica resulta sobretudo da relação entre os sentidos de “voz” e “microfone”, pois o trecho$text$, $text$A voz representa tanto a possibilidade de falar quanto a participação efetiva. O microfone exclusivo do chefe rompe a igualdade anunciada e revela concentração do poder decisório.$text$, 'B', $text$atribui a divergência exclusivamente a uma falha técnica acidental.$text$, $text$contrapõe a participação declarada à concentração efetiva do poder de decidir.$text$, $text$sustenta que a presença de equipamentos garante decisões democráticas.$text$, $text$iguala o direito de falar à autoridade de decidir em qualquer organização.$text$, $text$descreve literalmente uma reunião sem produzir avaliação das relações de poder.$text$),
        ('Q13', 'LINGUAGENS', 'Literatura', 'Realismo e Naturalismo', $text$Em uma narrativa autoral, um proprietário declara defender a liberdade, mas descreve seus trabalhadores apenas como “braços necessários à colheita”. O narrador reproduz o discurso e apresenta os baixos pagamentos, sem emitir uma condenação explícita. A crítica social se constrói pela$text$, $text$A justaposição entre a defesa abstrata da liberdade e a redução de pessoas à força de trabalho permite ao leitor identificar uma contradição. A crítica pode operar pela composição narrativa, sem julgamento explícito.$text$, 'C', $text$idealização do proprietário como modelo coerente de comportamento.$text$, $text$eliminação da perspectiva do leitor por uma conclusão moral expressa.$text$, $text$exposição da contradição entre o discurso do personagem e suas práticas.$text$, $text$apresentação do trabalho como fenômeno independente das relações econômicas.$text$, $text$valorização da desumanização como condição natural de toda narrativa.$text$),
        ('Q14', 'LINGUAGENS', 'Literatura', 'Poesia', $text$Considere o poema autoral: “Primeiro, a fábrica marcava as horas. / Depois, o apito marcava os corpos. / Agora, meu sono ainda troca de turno.” A progressão dos versos representa$text$, $text$O poema parte da organização externa do tempo e chega à persistência do ritmo de trabalho no sono. O efeito sugere que a disciplina fabril ultrapassa o espaço e o horário de produção.$text$, 'D', $text$a superação completa da disciplina industrial após o expediente.$text$, $text$uma cronologia técnica das mudanças na produção de relógios.$text$, $text$a equivalência entre descanso e trabalho como escolha livre do sujeito.$text$, $text$a incorporação do ritmo do trabalho à experiência íntima do sujeito.$text$, $text$a impossibilidade de usar acontecimentos sociais como matéria poética.$text$),
        ('Q15', 'LINGUAGENS', 'Artes', 'Arte Brasileira', $text$Um coletivo recria uma técnica artesanal tradicional em uma instalação feita com materiais reaproveitados. Os artesãos participam da concepção, são identificados como coautores e recebem parte da remuneração. Nesse caso, a relação entre tradição e produção contemporânea se caracteriza pela$text$, $text$A participação na concepção, o reconhecimento e a remuneração sustentam uma colaboração que transforma a técnica sem apagar seus produtores. A atualização não exige preservar todos os usos originais.$text$, 'E', $text$preservação da técnica por meio da proibição de novos materiais.$text$, $text$dissolução da autoria artesanal no anonimato obrigatório da tradição.$text$, $text$substituição do conhecimento dos artesãos pela interpretação exclusiva do coletivo.$text$, $text$conversão automática de qualquer reaproveitamento em preservação cultural.$text$, $text$atualização de um saber com reconhecimento da autoria de seus detentores.$text$),
        ('Q16', 'LINGUAGENS', 'Educação Física', 'Esporte e Sociedade', $text$Uma escola selecionava para os jogos apenas estudantes com melhor desempenho. Após debate, mantém uma equipe competitiva e cria rodízios, adaptações de regras e atividades de iniciação para os demais. A mudança amplia a dimensão educativa do esporte porque$text$, $text$A proposta preserva a competição, mas acrescenta caminhos de acesso e aprendizagem. O direito à prática não fica condicionado ao rendimento previamente alcançado.$text$, 'A', $text$articula busca de desempenho com oportunidades de participação e aprendizagem.$text$, $text$faz da vitória o critério único para avaliar a aprendizagem de todos.$text$, $text$torna desnecessário ensinar habilidades específicas das modalidades.$text$, $text$pressupõe que adaptar regras elimina qualquer desafio corporal.$text$, $text$condiciona a inclusão à obtenção posterior de resultados competitivos.$text$),
        ('Q17', 'LINGUAGENS', 'Educação Física', 'Corpo e Cultura', $text$Uma publicidade associa um único tipo corporal à saúde. Em resposta, um grupo publica relatos de pessoas com corpos diversos que praticam atividades físicas, reconhecendo que a avaliação de saúde exige outros indicadores. Essa resposta questiona principalmente a$text$, $text$A aparência não resume as condições de saúde. Os relatos contestam a associação automática entre um padrão estético e o bem-estar, sem afirmar que toda pessoa fisicamente ativa tem saúde garantida.$text$, 'B', $text$utilização de qualquer indicador para acompanhar a saúde.$text$, $text$redução da saúde à conformidade com um padrão estético.$text$, $text$possibilidade de realizar exercícios fora de ambientes esportivos.$text$, $text$necessidade de considerar as condições individuais da prática corporal.$text$, $text$existência de relações entre atividade física e bem-estar.$text$),
        ('Q18', 'LINGUAGENS', 'Tecnologias da Informação e Comunicação', 'Mídias e Informação', $text$Uma postagem anuncia que uma cidade “dobrou seus casos” de determinado problema. O link mostra aumento de 2 para 4 registros, em períodos com números diferentes de moradores atendidos. Antes de comparar o risco entre os períodos, qual procedimento é indispensável?$text$, $text$O aumento relativo dos registros é de 100%, mas não informa, sozinho, a frequência entre os atendidos. Comparar taxas com denominadores e critérios compatíveis evita confundir contagem e risco.$text$, 'C', $text$Substituir os números absolutos pela manchete, pois ela já resume a tendência.$text$, $text$Concluir que o risco individual dobrou sempre que a contagem duplicou.$text$, $text$Relacionar os registros ao total de atendidos e verificar a comparabilidade da coleta.$text$, $text$Descartar os dados apenas porque os números de registros são pequenos.$text$, $text$Somar os registros dos períodos e dividir por dois, ignorando os atendimentos.$text$),
        ('Q19', 'LINGUAGENS', 'Tecnologias da Informação e Comunicação', 'Cultura Digital', $text$Uma plataforma passa a recomendar conteúdos semelhantes aos que cada usuário já consome. Após meses, uma estudante conclui que “todos concordam” com sua opinião porque raramente encontra divergências. A conclusão é limitada porque$text$, $text$As recomendações selecionam o que aparece com base no comportamento anterior. O conjunto visto é filtrado e não constitui uma amostra representativa de todas as posições existentes.$text$, 'D', $text$o número de conteúdos vistos garante a representatividade das opiniões exibidas.$text$, $text$os algoritmos impedem que qualquer usuário publique posições divergentes.$text$, $text$a concordância entre publicações demonstra a veracidade das afirmações.$text$, $text$a seleção personalizada pode tornar pouco visíveis posições presentes fora de seu circuito.$text$, $text$a personalização elimina a influência das escolhas anteriores do usuário.$text$),
        ('Q20', 'LINGUAGENS', 'Língua Portuguesa', 'Gramática Aplicada ao Texto', $text$Compare as manchetes autorais: I. “Empresa despeja resíduos no rio durante a madrugada”. II. “Resíduos são despejados no rio durante a madrugada”. Embora ambas possam descrever o mesmo evento, a segunda produz um efeito discursivo específico ao$text$, $text$A voz passiva sem agente mantém o acontecimento e os resíduos em destaque, mas deixa de identificar quem praticou a ação. Isso pode reduzir a visibilidade da responsabilidade sem negar o despejo.$text$, 'E', $text$transformar o despejo em um evento futuro e incerto.$text$, $text$atribuir a ação aos moradores próximos do rio.$text$, $text$negar a ocorrência do evento apresentado na primeira.$text$, $text$tornar mais precisa a informação sobre a autoria da ação.$text$, $text$retirar da formulação a identificação explícita do responsável pelo despejo.$text$),
        ('Q21', 'CIENCIAS_HUMANAS', 'História', 'Brasil Colônia', $text$Em uma região colonial, grandes propriedades produziam açúcar para exportação, mas também compravam alimentos de pequenos produtores locais. A partir desse quadro, qual interpretação evita reduzir toda a economia colonial a uma única atividade?$text$, $text$A exportação estruturava relações fundamentais da colonização, mas convivia com circuitos de abastecimento e produtores voltados ao mercado interno. Reconhecer esses circuitos não elimina a centralidade do setor exportador.$text$, 'A', $text$A produção exportadora coexistia com atividades internas articuladas ao abastecimento.$text$, $text$O abastecimento local tornava a economia independente das relações coloniais.$text$, $text$A presença de pequenos produtores eliminava a concentração fundiária.$text$, $text$Toda produção de alimentos era destinada ao mercado europeu.$text$, $text$A exportação e o abastecimento interno eram circuitos necessariamente isolados.$text$),
        ('Q22', 'CIENCIAS_HUMANAS', 'História', 'Brasil Império', $text$Uma pesquisa sobre o período posterior à abolição identifica trabalhadores negros com liberdade jurídica, mas com acesso restrito à terra, à escolarização e a empregos valorizados. Que conclusão decorre da comparação entre a mudança legal e essas condições sociais?$text$, $text$A abolição extinguiu juridicamente a escravidão, mas não foi acompanhada de uma transformação suficiente das condições de acesso a recursos. Liberdade formal e igualdade material são dimensões distintas.$text$, 'B', $text$A abolição manteve legalmente a condição de propriedade sobre as pessoas libertas.$text$, $text$A conquista da liberdade jurídica não assegurou igualdade de oportunidades materiais.$text$, $text$A desigualdade posterior demonstra que a mudança jurídica não teve relevância.$text$, $text$As restrições de acesso decorreram apenas de escolhas individuais dos libertos.$text$, $text$A igualdade perante a lei suprimiu imediatamente as hierarquias raciais.$text$),
        ('Q23', 'CIENCIAS_HUMANAS', 'História', 'Primeira República', $text$Em um município da Primeira República, um chefe local intermediava empregos e favores e cobrava apoio eleitoral. A dependência econômica dos eleitores limitava a autonomia do voto. Esse mecanismo evidencia a$text$, $text$O controle de recursos e favores convertia dependência social em apoio político, característica de práticas coronelistas e clientelistas. A existência de eleições não garantia participação autônoma.$text$, 'C', $text$separação completa entre relações de trabalho e participação eleitoral.$text$, $text$universalização da cidadania pela simples realização de eleições.$text$, $text$articulação entre poder econômico local e controle político por relações de dependência.$text$, $text$subordinação dos chefes locais a associações independentes de trabalhadores.$text$, $text$distribuição impessoal de recursos segundo critérios públicos universais.$text$),
        ('Q24', 'CIENCIAS_HUMANAS', 'História', 'Era Vargas', $text$Durante o governo Vargas, direitos trabalhistas foram ampliados ao mesmo tempo que sindicatos eram submetidos à tutela estatal. A análise conjunta dessas medidas permite reconhecer uma política de$text$, $text$A incorporação de direitos favorecia a integração dos trabalhadores, enquanto a tutela sindical limitava sua organização autônoma. As duas dimensões compunham uma mesma estratégia de regulação do conflito social.$text$, 'D', $text$retirada completa do Estado das relações entre capital e trabalho.$text$, $text$concessão de autonomia sindical irrestrita em troca da suspensão de direitos.$text$, $text$eliminação dos conflitos de classe por meio da legislação.$text$, $text$incorporação de demandas sociais associada ao controle da organização dos trabalhadores.$text$, $text$substituição de todos os contratos de trabalho por vínculos com o serviço público.$text$),
        ('Q25', 'CIENCIAS_HUMANAS', 'História', 'Ditadura Militar no Brasil', $text$Um arquivo reúne notícias censuradas e campanhas oficiais de crescimento econômico produzidas no mesmo período da ditadura militar. Comparar esses conjuntos documentais contribui para compreender como o regime$text$, $text$A propaganda destacava realizações, enquanto a censura restringia a circulação de críticas. A comparação permite analisar mecanismos complementares de construção de legitimidade e controle do debate público.$text$, 'E', $text$garantia pluralidade informativa pela existência de campanhas oficiais.$text$, $text$substituía a coerção por consenso livre de restrições.$text$, $text$impedia a produção de qualquer documento sobre economia.$text$, $text$tornava a imprensa independente das disputas políticas.$text$, $text$combinava divulgação de realizações com restrição das críticas públicas.$text$),
        ('Q26', 'CIENCIAS_HUMANAS', 'História', 'Revolução Industrial', $text$Em uma oficina artesanal, um trabalhador organizava etapas variadas da produção. Na fábrica, passou a repetir uma operação conforme o ritmo das máquinas e horários definidos pela administração. A mudança descrita envolve principalmente$text$, $text$A fragmentação das tarefas e a imposição de horários transferem o controle do processo e do tempo de trabalho para a direção fabril. Isso não significa que o trabalhador deixou de possuir qualquer conhecimento.$text$, 'A', $text$redução da autonomia sobre o processo e o tempo de trabalho.$text$, $text$ampliação do controle individual sobre o ritmo da produção.$text$, $text$desaparecimento de toda qualificação profissional nas cidades.$text$, $text$retorno à produção doméstica orientada pelo consumo familiar.$text$, $text$subordinação das máquinas ao ritmo escolhido por cada operário.$text$),
        ('Q27', 'CIENCIAS_HUMANAS', 'Geografia', 'Urbanização', $text$Uma cidade amplia vias expressas, mas o tempo médio de deslocamento de moradores periféricos cresce. No mesmo período, empregos se concentram no centro e novas moradias populares surgem mais longe dele. Que medida enfrenta a dimensão territorial do problema?$text$, $text$A distância entre moradia e oportunidades ajuda a explicar o aumento dos deslocamentos. Aproximar serviços e empregos das áreas residenciais e conectar o transporte coletivo enfrenta essa estrutura, além da capacidade viária.$text$, 'B', $text$Aumentar exclusivamente a velocidade máxima nas vias centrais.$text$, $text$Distribuir oportunidades pelo território e integrá-las a uma rede de transporte coletivo.$text$, $text$Concentrar novos serviços na área que já reúne os empregos.$text$, $text$Remover linhas de ônibus pouco rentáveis sem oferecer alternativas.$text$, $text$Substituir toda política de uso do solo por incentivos à compra de automóveis.$text$),
        ('Q28', 'CIENCIAS_HUMANAS', 'Geografia', 'Climatologia', $text$Duas áreas de uma cidade apresentam temperaturas distintas à noite. A primeira tem muito asfalto, edifícios densos e pouca vegetação; a segunda possui parques e solo permeável. Em condições meteorológicas semelhantes, a diferença pode ser explicada pela$text$, $text$Materiais urbanos armazenam calor e o liberam depois, enquanto a menor vegetação reduz o resfriamento por evapotranspiração. Esses fatores contribuem para a ilha de calor.$text$, 'C', $text$maior latitude da área asfaltada dentro do mesmo bairro.$text$, $text$redução da absorção solar por todas as superfícies escuras.$text$, $text$maior retenção de calor e menor evapotranspiração na área mais impermeabilizada.$text$, $text$elevação obrigatória da umidade do ar em superfícies impermeáveis.$text$, $text$produção de calor exclusivamente pela fotossíntese dos parques.$text$),
        ('Q29', 'CIENCIAS_HUMANAS', 'Geografia', 'População e Demografia', $text$Um país apresenta queda prolongada da fecundidade e aumento da expectativa de vida. A população total ainda cresce, mas a proporção de idosos aumenta. Qual consequência deve orientar o planejamento público?$text$, $text$A mudança da estrutura etária pode elevar a demanda por cuidados prolongados e alterar a relação entre grupos etários. O crescimento total não implica aumento da proporção de crianças.$text$, 'D', $text$Ampliar maternidades supondo aumento obrigatório da proporção de crianças.$text$, $text$Reduzir cuidados continuados porque maior longevidade elimina doenças crônicas.$text$, $text$Concluir que a população total já está diminuindo apenas pelo envelhecimento.$text$, $text$Reorganizar cuidados e proteção social considerando a mudança da estrutura etária.$text$, $text$Manter a mesma distribuição de serviços, pois o total populacional ainda cresce.$text$),
        ('Q30', 'CIENCIAS_HUMANAS', 'Geografia', 'Cartografia', $text$Dois mapas mundiais usam projeções diferentes: um preserva áreas relativas e outro preserva ângulos localmente, ampliando regiões de altas latitudes. Para comparar a extensão territorial de países, qual escolha é mais adequada?$text$, $text$Uma projeção equivalente preserva proporções de área, apropriadas à comparação territorial. Preservar ângulos não garante preservar áreas, e toda projeção plana envolve deformações.$text$, 'E', $text$Usar o mapa conforme, porque preservar ângulos garante preservar superfícies.$text$, $text$Escolher apenas o mapa de maior tamanho impresso, independentemente da projeção.$text$, $text$Comparar larguras aparentes sem considerar a posição dos países.$text$, $text$Evitar qualquer mapa, pois deformações impedem todas as comparações.$text$, $text$Usar o mapa equivalente, reconhecendo que ele também distorce outras propriedades.$text$),
        ('Q31', 'CIENCIAS_HUMANAS', 'Geografia', 'Globalização', $text$Uma empresa projeta um produto em um país, compra componentes em outros e terceiriza a montagem onde os salários são menores. Uma interrupção em um único fornecedor paralisa fábricas em vários continentes. O caso revela que as redes globais de produção$text$, $text$A fragmentação espacial permite especialização e redução de custos, mas cria dependências entre etapas distantes. Por isso, problemas localizados podem propagar-se pela rede.$text$, 'A', $text$combinam dispersão das etapas produtivas com interdependência entre territórios.$text$, $text$tornam cada unidade produtiva independente dos fluxos internacionais.$text$, $text$distribuem igualmente os ganhos e os riscos entre todos os países.$text$, $text$eliminam a importância das infraestruturas locais de transporte.$text$, $text$impedem que decisões empresariais afetem mercados de trabalho distantes.$text$),
        ('Q32', 'CIENCIAS_HUMANAS', 'Geografia', 'Questões Ambientais', $text$Uma obra de contenção protege um trecho da margem de um rio, mas acelera o fluxo e amplia a erosão a jusante. Moradores de outro município passam a sofrer perdas. Que princípio de gestão é reforçado por esse resultado?$text$, $text$Os processos fluviais conectam trechos do rio e ultrapassam limites municipais. A avaliação por bacia permite considerar efeitos transferidos para outras áreas.$text$, 'B', $text$Avaliar a obra apenas pela estabilidade da margem imediatamente protegida.$text$, $text$Planejar intervenções na escala da bacia, considerando efeitos além do local da obra.$text$, $text$Separar a gestão do rio segundo limites administrativos sem coordenação.$text$, $text$Tratar a erosão a jusante como fenômeno sem relação com intervenções a montante.$text$, $text$Priorizar soluções idênticas em todos os trechos, independentemente do fluxo.$text$),
        ('Q33', 'CIENCIAS_HUMANAS', 'Geografia', 'Agropecuária', $text$Uma região eleva a produção agrícola com mecanização e insumos, enquanto reduz empregos diretos no campo. Parte dos antigos trabalhadores se desloca para cidades próximas. A interpretação mais adequada desse processo é que$text$, $text$O aumento da produtividade por trabalhador permite produzir mais com menos emprego direto. Portanto, crescimento da produção e expansão do trabalho rural não são equivalentes.$text$, 'C', $text$a queda do emprego comprova redução obrigatória do volume produzido.$text$, $text$a mecanização impede qualquer atividade econômica nas cidades próximas.$text$, $text$o avanço da produtividade pode coexistir com redução da demanda direta por trabalho rural.$text$, $text$o êxodo rural decorre exclusivamente de fatores naturais.$text$, $text$a produtividade depende apenas da ampliação da área cultivada.$text$),
        ('Q34', 'CIENCIAS_HUMANAS', 'Filosofia', 'Ética', $text$Um gestor afirma que uma decisão é justa porque beneficia a maioria. Uma conselheira responde que o benefício coletivo não basta para justificar a violação de direitos fundamentais de um grupo pequeno. A divergência opõe principalmente$text$, $text$O gestor privilegia o saldo de consequências, enquanto a conselheira estabelece limites fundados em direitos. O conflito envolve critérios de justificação moral, não apenas previsões sobre resultados.$text$, 'D', $text$o conhecimento científico e a rejeição de qualquer argumento racional.$text$, $text$a defesa da participação popular e a proibição de decisões coletivas.$text$, $text$a legalidade de uma medida e sua viabilidade técnica, sem discussão moral.$text$, $text$a avaliação pelas consequências e a imposição de limites baseados em direitos.$text$, $text$a preferência individual e a impossibilidade de formular princípios universais.$text$),
        ('Q35', 'CIENCIAS_HUMANAS', 'Filosofia', 'Teoria do Conhecimento', $text$Dois grupos observam que estudantes que frequentam uma biblioteca têm notas maiores. Um conclui que a biblioteca, sozinha, causa a diferença. O outro propõe investigar renda, tempo disponível e desempenho anterior. A segunda posição é mais rigorosa porque$text$, $text$A associação observada pode envolver seleção prévia e outras variáveis. Examinar explicações alternativas é necessário para sustentar uma inferência causal, embora não garanta por si só uma conclusão definitiva.$text$, 'E', $text$considera impossível produzir conhecimento a partir de observações.$text$, $text$substitui evidências por preferências pessoais sobre educação.$text$, $text$presume que a renda é sempre a única causa do desempenho.$text$, $text$nega que o uso da biblioteca possa ter qualquer efeito sobre a aprendizagem.$text$, $text$distingue associação observada de explicação causal e examina fatores concorrentes.$text$),
        ('Q36', 'CIENCIAS_HUMANAS', 'Filosofia', 'Filosofia Política', $text$Uma assembleia aprova uma regra por maioria, mas impede os diretamente afetados de apresentar argumentos antes da votação. À luz de uma concepção deliberativa de democracia, qual é o principal problema do procedimento?$text$, $text$A deliberação democrática requer possibilidade de apresentação e contestação de razões pelos participantes. Contar votos é relevante, mas não substitui a inclusão no debate.$text$, 'A', $text$A decisão majoritária foi tomada sem assegurar participação na formação pública das razões.$text$, $text$A existência de divergências torna qualquer votação ilegítima.$text$, $text$Uma regra só pode ser democrática se aprovada por unanimidade.$text$, $text$A participação dos afetados deve ocorrer apenas depois da decisão.$text$, $text$O número de votos dispensa a análise das condições do debate.$text$),
        ('Q37', 'CIENCIAS_HUMANAS', 'Sociologia', 'Trabalho e Sociedade', $text$Entregadores controlam o horário de conexão a uma plataforma, mas recebem menos chamadas quando recusam serviços e não conhecem os critérios de distribuição. Essa combinação permite discutir a$text$, $text$A liberdade de conexão convive com incentivos e sanções mediados por critérios pouco transparentes. O controle pode ocorrer por mecanismos algorítmicos, mesmo sem ordens presenciais de uma chefia.$text$, 'B', $text$ausência de relações de poder quando não há supervisão presencial.$text$, $text$existência de controle do trabalho mesmo sob uma autonomia formal de horários.$text$, $text$equivalência entre possuir um veículo e controlar os critérios de remuneração.$text$, $text$eliminação da dependência econômica pela possibilidade de desconectar.$text$, $text$impossibilidade de organizar trabalhadores que executam tarefas fora de fábricas.$text$),
        ('Q38', 'CIENCIAS_HUMANAS', 'Sociologia', 'Desigualdade Social', $text$Uma universidade oferece inscrição gratuita, mas exige prova presencial distante e documentação obtida apenas em horário comercial. Candidatos com menor renda desistem em maior proporção. O caso mostra que$text$, $text$Custos de transporte, disponibilidade de tempo e acesso a documentos afetam a participação. A gratuidade remove uma barreira, mas não garante condições efetivas equivalentes.$text$, 'C', $text$a gratuidade assegura condições idênticas a todos os candidatos.$text$, $text$a desistência mede diretamente a capacidade intelectual dos candidatos.$text$, $text$a igualdade formal de acesso pode coexistir com barreiras materiais à participação.$text$, $text$os procedimentos administrativos não influenciam desigualdades sociais.$text$, $text$a renda só interfere no acesso quando há cobrança de mensalidades.$text$),
        ('Q39', 'CIENCIAS_HUMANAS', 'Sociologia', 'Movimentos Sociais', $text$Moradores coletam dados sobre alagamentos, organizam reuniões e exigem participação na definição das obras de drenagem. Ao transformar experiências individuais em uma pauta coletiva, sua ação caracteriza$text$, $text$O movimento identifica um problema comum e disputa prioridades públicas por organização e participação. O uso de dados técnicos pode integrar, e não excluir, a ação política.$text$, 'D', $text$a substituição obrigatória do governo por uma associação privada.$text$, $text$a rejeição do conhecimento técnico como parte da participação política.$text$, $text$a redução do problema urbano a escolhas domésticas isoladas.$text$, $text$a politização de uma demanda cotidiana por organização e reivindicação coletiva.$text$, $text$a suspensão da cidadania enquanto as obras não forem concluídas.$text$),
        ('Q40', 'CIENCIAS_HUMANAS', 'Sociologia', 'Identidade e Diversidade', $text$Uma comunidade reivindica reconhecimento de sua tradição, mas seus jovens incorporam novas músicas e formas de vestir. Um pesquisador afirma que essas mudanças não anulam o pertencimento coletivo. Essa interpretação entende a cultura como$text$, $text$Práticas culturais se transformam nas relações entre gerações e grupos. O pertencimento pode ser reelaborado sem depender de uma reprodução imutável de todos os costumes.$text$, 'E', $text$um inventário fixo cuja alteração elimina qualquer identidade.$text$, $text$um atributo biológico transmitido sem aprendizagem social.$text$, $text$um conjunto de hábitos individuais sem relações com a vida coletiva.$text$, $text$uma herança legítima apenas quando isolada de contatos externos.$text$, $text$um processo histórico de reelaboração de práticas e sentidos compartilhados.$text$),
        ('Q41', 'CIENCIAS_DA_NATUREZA', 'Biologia', 'Ecologia', $text$Um lago recebe esgoto rico em nutrientes. Após uma proliferação de algas, ocorre grande mortalidade de peixes, sobretudo de madrugada. Qual sequência explica melhor o fenômeno?$text$, $text$O enriquecimento favorece a produção de biomassa. A decomposição e a respiração consomem oxigênio; de madrugada, a ausência de fotossíntese agrava sua redução, comprometendo os peixes.$text$, 'A', $text$Aumento de biomassa, intensificação da decomposição e queda do oxigênio dissolvido.$text$, $text$Redução de nutrientes, interrupção da respiração e acúmulo de oxigênio.$text$, $text$Produção de oxigênio pelas bactérias decompositoras e intoxicação dos peixes.$text$, $text$Aumento permanente da fotossíntese noturna e elevação do pH como única causa.$text$, $text$Consumo direto de todos os peixes pelas algas após a floração.$text$),
        ('Q42', 'CIENCIAS_DA_NATUREZA', 'Biologia', 'Genética', $text$Uma condição autossômica recessiva manifesta-se em indivíduos aa. Um casal sem a condição já teve um filho afetado. Admitindo penetrância completa, ausência de novas mutações e segregação independente entre gestações, qual é a probabilidade de os próximos dois filhos não manifestarem a condição?$text$, $text$O filho aa indica que ambos os pais não afetados são Aa. Cada gestação tem probabilidade 3/4 de gerar alguém não afetado. Para duas gestações independentes: (3/4)² = 9/16.$text$, 'B', $text$1/16.$text$, $text$9/16.$text$, $text$1/4.$text$, $text$1/2.$text$, $text$3/4.$text$),
        ('Q43', 'CIENCIAS_DA_NATUREZA', 'Biologia', 'Evolução', $text$Após aplicações repetidas de um inseticida, aumenta a proporção de insetos resistentes. Amostras anteriores ao uso já continham raros indivíduos com a variante associada à resistência. A evidência favorece qual explicação?$text$, $text$A variante preexistia e seus portadores tiveram maior sucesso relativo sob o inseticida. A seleção altera frequências de variantes; não exige que o produto induza mutações dirigidas pela necessidade.$text$, 'C', $text$O contato ensinou todos os insetos a produzir a mesma mutação útil.$text$, $text$A resistência surgiu porque cada inseto decidiu evitar o composto.$text$, $text$O inseticida favoreceu a sobrevivência e reprodução de portadores de uma variante preexistente.$text$, $text$A variante só pode ter surgido depois da primeira aplicação.$text$, $text$Os insetos sensíveis transformaram-se em resistentes por uso mais intenso de seus órgãos.$text$),
        ('Q44', 'CIENCIAS_DA_NATUREZA', 'Biologia', 'Citologia', $text$Hemácias são colocadas em uma solução com concentração de solutos efetivamente não permeantes menor que a de seu citoplasma. A membrana permite a passagem de água. O que se espera inicialmente e por quê?$text$, $text$O meio externo é hipotônico em relação ao interior. A entrada de água por osmose aumenta o volume celular e pode causar hemólise, pois hemácias não possuem parede celular.$text$, 'D', $text$Saída de água por transporte ativo, com retração celular.$text$, $text$Entrada de solutos por osmose, sem mudança no volume.$text$, $text$Saída de água por difusão, pois o meio externo é hipotônico.$text$, $text$Entrada de água por osmose, com aumento do volume celular.$text$, $text$Manutenção obrigatória do volume pela presença de parede celular.$text$),
        ('Q45', 'CIENCIAS_DA_NATUREZA', 'Biologia', 'Fisiologia Humana', $text$Durante uma atividade, o aumento do gás carbônico no sangue favorece a formação de íons H+, reduzindo o pH. Em uma pessoa saudável, a resposta ventilatória ajuda a compensar essa alteração porque$text$, $text$O aumento da ventilação elimina mais CO₂. No equilíbrio CO₂ + H₂O ⇌ H₂CO₃ ⇌ H+ + HCO₃−, a redução de CO₂ favorece diminuição de H+, contribuindo para recuperar o pH.$text$, 'E', $text$a retenção de CO₂ reduz a acidez do sangue.$text$, $text$os pulmões excretam diretamente todo o ácido lático em forma de gás.$text$, $text$a diminuição da ventilação aumenta obrigatoriamente a oxigenação.$text$, $text$a entrada de oxigênio transforma quimicamente todos os íons H+ em glicose.$text$, $text$a maior eliminação de CO₂ contribui para reduzir a concentração de H+.$text$),
        ('Q46', 'CIENCIAS_DA_NATUREZA', 'Biologia', 'Botânica', $text$Em um dia quente e seco, uma planta fecha parcialmente os estômatos. A medida reduz a perda de água, mas também pode diminuir a fotossíntese. Qual relação explica esse custo fisiológico?$text$, $text$Os estômatos participam das trocas gasosas. Seu fechamento reduz a transpiração, mas limita a difusão de CO₂ para o interior da folha, diminuindo a disponibilidade de substrato para a fixação de carbono.$text$, 'A', $text$O fechamento limita simultaneamente a saída de vapor de água e a entrada de CO₂.$text$, $text$A água deixa de chegar às folhas porque os estômatos são os vasos do xilema.$text$, $text$A clorofila é eliminada pelos estômatos quando eles se fecham.$text$, $text$A respiração celular exige luz e é interrompida pelo fechamento.$text$, $text$O fechamento aumenta a entrada de CO₂ e reduz sua fixação por excesso de substrato.$text$),
        ('Q47', 'CIENCIAS_DA_NATUREZA', 'Biologia', 'Biotecnologia', $text$Uma bactéria recebe um plasmídeo com um gene de interesse e um marcador de resistência a certo antibiótico. Após a transformação, o cultivo é feito em meio com esse antibiótico. Considerando bactérias inicialmente sensíveis, essa etapa permite principalmente$text$, $text$O antibiótico seleciona células que adquiriram resistência, compatível com a presença do plasmídeo. A seleção não demonstra, por si só, expressão correta ou funcionalidade do produto do gene de interesse.$text$, 'B', $text$garantir que toda célula sobrevivente produziu a proteína de interesse corretamente.$text$, $text$selecionar candidatas portadoras do plasmídeo, sem comprovar por si só a produção funcional da proteína.$text$, $text$induzir a mesma mutação no gene de interesse de todas as bactérias.$text$, $text$eliminar o plasmídeo das células que incorporaram o gene.$text$, $text$comprovar que a proteína produzida não oferece nenhum risco em qualquer uso.$text$),
        ('Q48', 'CIENCIAS_DA_NATUREZA', 'Física', 'Cinemática', $text$Um ônibus percorre 12 km a 24 km/h e, depois, outros 12 km a 48 km/h, sem paradas. Um passageiro calcula a velocidade média como 36 km/h, média aritmética das velocidades. Qual é a velocidade média correta no percurso total?$text$, $text$Os tempos são 12/24 = 0,5 h e 12/48 = 0,25 h. A velocidade média é 24/0,75 = 32 km/h. A média aritmética seria adequada para tempos iguais, não para distâncias iguais.$text$, 'C', $text$30 km/h.$text$, $text$36 km/h.$text$, $text$32 km/h.$text$, $text$40 km/h.$text$, $text$42 km/h.$text$),
        ('Q49', 'CIENCIAS_DA_NATUREZA', 'Física', 'Trabalho e Energia', $text$Uma bomba eleva 600 L de água a uma altura de 12 m em 2 min. Considere densidade da água de 1 kg/L, g = 10 m/s² e rendimento global de 60%. Qual potência elétrica média é necessária, desprezando outros efeitos além dos incluídos no rendimento?$text$, $text$A energia útil é mgh = 600 × 10 × 12 = 72 000 J. Em 120 s, a potência útil é 600 W. Como o rendimento é 0,60, a potência elétrica é 600/0,60 = 1 000 W.$text$, 'D', $text$360 W.$text$, $text$600 W.$text$, $text$720 W.$text$, $text$1 000 W.$text$, $text$1 200 W.$text$),
        ('Q50', 'CIENCIAS_DA_NATUREZA', 'Física', 'Eletricidade', $text$Um chuveiro resistivo de resistência constante, projetado para 220 V, é ligado a 110 V. No modelo ideal e mantendo a mesma vazão e a temperatura de entrada da água, a elevação de temperatura da água será que fração da original?$text$, $text$Para resistência constante, P = V²/R. A tensão cai à metade e a potência a um quarto. Com a mesma vazão, P = vazão mássica × calor específico × variação de temperatura, logo a elevação também cai a um quarto.$text$, 'E', $text$Metade.$text$, $text$Dois terços.$text$, $text$O dobro.$text$, $text$A mesma fração unitária.$text$, $text$Um quarto.$text$),
        ('Q51', 'CIENCIAS_DA_NATUREZA', 'Física', 'Termologia', $text$Um coletor recebe 400 W de potência solar efetivamente absorvida e a transfere integralmente a 20 kg de água durante 35 min. Considere calor específico da água de 4 200 J/(kg·°C), sem mudança de fase nem perdas. Qual é a elevação de temperatura?$text$, $text$O tempo é 2 100 s e a energia é 400 × 2 100 = 840 000 J. Pela relação Q = mcΔT, ΔT = 840 000/(20 × 4 200) = 10 °C.$text$, 'A', $text$10 °C.$text$, $text$2 °C.$text$, $text$5 °C.$text$, $text$20 °C.$text$, $text$35 °C.$text$),
        ('Q52', 'CIENCIAS_DA_NATUREZA', 'Física', 'Ondulatória', $text$Uma onda sonora de frequência 680 Hz propaga-se no ar a 340 m/s e entra em água, onde sua velocidade é 1 500 m/s. A fonte permanece a mesma. Qual alteração ocorre na passagem entre os meios?$text$, $text$A frequência é determinada pela fonte e permanece 680 Hz. Pela relação λ = v/f, o comprimento de onda passa de 0,50 m para aproximadamente 2,21 m.$text$, 'B', $text$A frequência aumenta e o comprimento de onda permanece constante.$text$, $text$A frequência permanece constante e o comprimento de onda aumenta.$text$, $text$A frequência e o comprimento de onda diminuem na mesma proporção.$text$, $text$A velocidade aumenta e a frequência passa obrigatoriamente a 3 000 Hz.$text$, $text$O comprimento de onda permanece em 0,50 m e a velocidade não se altera.$text$),
        ('Q53', 'CIENCIAS_DA_NATUREZA', 'Física', 'Óptica', $text$Uma lupa é modelada por uma lente delgada convergente de distância focal 10 cm. Um pequeno objeto é colocado a 6 cm da lente. Pelo modelo de Gauss, qual imagem é formada?$text$, $text$Na equação 1/f = 1/p + 1/p', 1/p' = 1/10 − 1/6 = −1/15, portanto p' = −15 cm. A ampliação é −p'/p = 2,5, positiva: imagem virtual, direita e ampliada.$text$, 'C', $text$Real, invertida e 2,5 vezes maior.$text$, $text$Virtual, invertida e 0,4 vez o tamanho.$text$, $text$Virtual, direita e 2,5 vezes maior.$text$, $text$Real, direita e do mesmo tamanho.$text$, $text$Virtual, direita e 0,4 vez o tamanho.$text$),
        ('Q54', 'CIENCIAS_DA_NATUREZA', 'Física', 'Hidrostática', $text$Um bloco homogêneo flutua em água com 75% do volume submerso. Ele é transferido para um líquido de densidade 1,2 g/cm³. Considere densidade da água de 1,0 g/cm³ e equilíbrio em ambos os casos. Que porcentagem do volume fica submersa no novo líquido?$text$, $text$Na água, a densidade do bloco é 0,75 × 1,0 = 0,75 g/cm³. No novo líquido, a fração submersa é 0,75/1,2 = 0,625, equivalente a 62,5%.$text$, 'D', $text$50,0%.$text$, $text$75,0%.$text$, $text$80,0%.$text$, $text$62,5%.$text$, $text$90,0%.$text$),
        ('Q55', 'CIENCIAS_DA_NATUREZA', 'Química', 'Estequiometria', $text$Um calcário contém 80% em massa de CaCO₃. Na reação CaCO₃ → CaO + CO₂, uma amostra de 250 g é processada com rendimento de 90% para produção de CaO. Use massas molares de 100 g/mol para CaCO₃ e 56 g/mol para CaO. Qual massa de CaO é obtida?$text$, $text$Há 250 × 0,80 = 200 g de CaCO₃, ou 2 mol. A massa teórica de CaO é 2 × 56 = 112 g. Com 90% de rendimento, obtêm-se 100,8 g.$text$, 'E', $text$89,6 g.$text$, $text$112,0 g.$text$, $text$126,0 g.$text$, $text$140,0 g.$text$, $text$100,8 g.$text$),
        ('Q56', 'CIENCIAS_DA_NATUREZA', 'Química', 'Soluções', $text$Uma solução aquosa contém 40 g/L de soluto. Retiram-se 150 mL, que são diluídos até 500 mL. Em seguida, 100 mL dessa solução diluída são completados até 300 mL. Sem perda de soluto, qual é a concentração final?$text$, $text$A primeira diluição produz 40 × 150/500 = 12 g/L. A segunda produz 12 × 100/300 = 4 g/L. Em cada etapa, conserva-se a massa de soluto na alíquota retirada.$text$, 'A', $text$4 g/L.$text$, $text$6 g/L.$text$, $text$8 g/L.$text$, $text$12 g/L.$text$, $text$20 g/L.$text$),
        ('Q57', 'CIENCIAS_DA_NATUREZA', 'Química', 'Termoquímica', $text$Para aquecer a mesma quantidade de água, comparam-se dois combustíveis: A libera 30 kJ/g com eficiência de transferência de 40%; B libera 20 kJ/g com eficiência de 75%. Considerando apenas a energia útil transferida, qual opção requer menor massa?$text$, $text$A fornece 30 × 0,40 = 12 kJ úteis por grama; B fornece 20 × 0,75 = 15 kJ/g. Para a mesma energia útil, mB/mA = 12/15 = 0,80: B usa 20% menos massa.$text$, 'B', $text$A, com massa 20% menor que a de B.$text$, $text$B, com massa 20% menor que a de A.$text$, $text$A, pois o poder calorífico isolado determina o consumo útil.$text$, $text$B, com massa 50% menor que a de A.$text$, $text$Ambos, com a mesma massa por terem eficiências diferentes.$text$),
        ('Q58', 'CIENCIAS_DA_NATUREZA', 'Química', 'Eletroquímica', $text$Uma tubulação de ferro é conectada a blocos de magnésio enterrados no mesmo solo úmido. O potencial padrão de redução do Mg²+/Mg é mais negativo que o do Fe²+/Fe. A proteção ocorre porque o magnésio$text$, $text$O magnésio tem maior tendência a oxidar-se nesse par e atua como ânodo de sacrifício. Ele fornece elétrons, favorecendo a preservação do ferro, e precisa ser reposto ao ser consumido.$text$, 'C', $text$se reduz preferencialmente e retira elétrons do ferro.$text$, $text$impede a corrosão sem sofrer qualquer transformação.$text$, $text$se oxida preferencialmente e fornece elétrons à estrutura de ferro.$text$, $text$transforma todo o ferro em uma liga inoxidável por contato.$text$, $text$neutraliza a umidade do solo por um processo exclusivamente físico.$text$),
        ('Q59', 'CIENCIAS_DA_NATUREZA', 'Química', 'Química Orgânica', $text$Um sabão remove gordura de um tecido quando usado em água. Suas moléculas possuem uma longa cadeia apolar e uma extremidade iônica. Qual arranjo explica a dispersão da gordura no meio aquoso?$text$, $text$As cadeias apolares interagem com a gordura e ficam voltadas para o interior das micelas; as extremidades iônicas interagem com a água. Essa organização permite dispersar o material oleoso.$text$, 'D', $text$Micelas com extremidades iônicas isoladas da água e cadeias expostas exclusivamente ao meio aquoso.$text$, $text$Conversão integral da gordura em água por quebra de todas as ligações de carbono.$text$, $text$Precipitação de toda a água ao redor do tecido por atração entre cargas iguais.$text$, $text$Micelas com cadeias apolares voltadas à gordura e extremidades iônicas em contato com a água.$text$, $text$Formação de uma solução gasosa de gordura pela evaporação do sabão.$text$),
        ('Q60', 'CIENCIAS_DA_NATUREZA', 'Química', 'Reações Químicas', $text$Em um recipiente fechado, o equilíbrio 2 NO₂(g) ⇌ N₂O₄(g) envolve NO₂ castanho e N₂O₄ incolor. A formação de N₂O₄ é exotérmica. Partindo do equilíbrio e mantendo o volume constante, o recipiente é resfriado. Qual alteração de composição é esperada no novo equilíbrio?$text$, $text$O resfriamento favorece o sentido exotérmico, que forma N₂O₄. Assim, a proporção de NO₂ diminui e a coloração castanha fica menos intensa. O volume é mantido constante para isolar a intervenção térmica.$text$, 'E', $text$Aumento da proporção de NO₂ porque o resfriamento favorece o sentido endotérmico.$text$, $text$Manutenção obrigatória da composição, pois temperatura só altera a velocidade.$text$, $text$Desaparecimento de todas as moléculas gasosas por conservação da massa.$text$, $text$Aumento de NO₂ causado exclusivamente pela presença de um catalisador.$text$, $text$Aumento da proporção de N₂O₄ e redução da intensidade da cor castanha.$text$),
        ('Q61', 'MATEMATICA', 'Matemática', 'Porcentagem', $text$Uma loja aumenta o preço de um produto em 25% e, depois, oferece um desconto sobre o novo preço para que o valor final seja 10% menor que o preço original. Qual deve ser o percentual desse desconto?$text$, $text$Se o preço original é P, após o aumento é 1,25P e o alvo é 0,90P. Logo, 1,25P(1 − d) = 0,90P, de onde d = 1 − 0,72 = 0,28.$text$, 'A', $text$28%.$text$, $text$15%.$text$, $text$20%.$text$, $text$30%.$text$, $text$35%.$text$),
        ('Q62', 'MATEMATICA', 'Matemática', 'Razão e Proporção', $text$Seis máquinas iguais, funcionando 8 horas por dia durante 5 dias, produzem 12 000 peças. Uma encomenda de 18 000 peças será feita em 4 dias, com jornada de 6 horas. Mantida a produtividade, qual é o menor número total de máquinas necessário?$text$, $text$A produtividade é 12 000/(6 × 8 × 5) = 50 peças por máquina-hora. Cada máquina produzirá 4 × 6 × 50 = 1 200 peças. São necessárias 18 000/1 200 = 15 máquinas.$text$, 'B', $text$9.$text$, $text$15.$text$, $text$10.$text$, $text$12.$text$, $text$18.$text$),
        ('Q63', 'MATEMATICA', 'Matemática', 'Funções', $text$Um serviço A cobra R$ 18,00 fixos mais R$ 2,40 por quilômetro. O serviço B cobra R$ 6,00 fixos mais R$ 3,20 por quilômetro. Para trajetos de comprimento x, em quilômetros, em qual condição A é estritamente mais barato?$text$, $text$A é mais barato se 18 + 2,4x < 6 + 3,2x. Assim, 12 < 0,8x e x > 15. Em 15 km os preços são iguais, portanto a desigualdade é estrita.$text$, 'C', $text$x < 15.$text$, $text$x > 12.$text$, $text$x > 15.$text$, $text$x ≥ 15.$text$, $text$x < 30.$text$),
        ('Q64', 'MATEMATICA', 'Matemática', 'Equações', $text$Uma cooperativa vende cestas por R$ 40,00 e R$ 55,00. Em um dia, vendeu 80 cestas e arrecadou R$ 3 650,00. Quantas cestas de R$ 55,00 foram vendidas?$text$, $text$Se x é o número de cestas de R$ 55, as outras são 80 − x. A receita é 55x + 40(80 − x) = 3 650, logo 15x = 450 e x = 30.$text$, 'D', $text$20.$text$, $text$25.$text$, $text$40.$text$, $text$30.$text$, $text$50.$text$),
        ('Q65', 'MATEMATICA', 'Matemática', 'Geometria Plana', $text$Um terreno retangular de 30 m por 20 m terá uma faixa interna de largura constante ao longo de todo o contorno. A região central restante deve ter 416 m². Qual será a largura da faixa?$text$, $text$Se a largura é x, (30 − 2x)(20 − 2x) = 416. Resulta x² − 25x + 46 = 0, com raízes 2 e 23. A raiz 23 é incompatível com o terreno; a faixa terá 2 m.$text$, 'E', $text$1 m.$text$, $text$3 m.$text$, $text$4 m.$text$, $text$5 m.$text$, $text$2 m.$text$),
        ('Q66', 'MATEMATICA', 'Matemática', 'Geometria Espacial', $text$Um reservatório cilíndrico de raio interno 1 m contém água até 1,2 m de altura. Uma bomba retira 20 L por minuto por 30 minutos. Adote π = 3 e despreze perdas. Qual é a altura final da água?$text$, $text$O volume inicial é 3 × 1² × 1,2 = 3,6 m³. A retirada é 600 L = 0,6 m³. Restam 3 m³; dividindo pela área da base de 3 m², a altura final é 1 m.$text$, 'A', $text$1,0 m.$text$, $text$0,6 m.$text$, $text$0,8 m.$text$, $text$1,1 m.$text$, $text$1,18 m.$text$),
        ('Q67', 'MATEMATICA', 'Matemática', 'Probabilidade', $text$Uma urna contém 5 fichas verdes e 3 amarelas. Duas fichas são retiradas sem reposição. Sabendo que pelo menos uma é amarela, qual é a probabilidade de ambas serem amarelas?$text$, $text$Há C(8,2) = 28 pares. Os pares com pelo menos uma amarela são 28 − C(5,2) = 18. Os pares com duas amarelas são C(3,2) = 3. A probabilidade condicional é 3/18 = 1/6.$text$, 'B', $text$3/28.$text$, $text$1/6.$text$, $text$1/4.$text$, $text$3/8.$text$, $text$1/2.$text$),
        ('Q68', 'MATEMATICA', 'Matemática', 'Estatística', $text$Em um curso, 20 estudantes obtiveram média 6,0, e outros 30 obtiveram média 8,0. Dez novos estudantes entram na turma. Para que a média dos 60 seja 7,5, qual deve ser a média dos novos estudantes?$text$, $text$A soma inicial é 20 × 6 + 30 × 8 = 360. A soma necessária é 60 × 7,5 = 450. Os dez novos precisam somar 90 pontos, com média 9,0.$text$, 'C', $text$7,0.$text$, $text$7,5.$text$, $text$9,0.$text$, $text$8,0.$text$, $text$8,5.$text$),
        ('Q69', 'MATEMATICA', 'Matemática', 'Progressões', $text$Uma campanha recolhe 150 kg de alimentos na primeira semana e amplia a arrecadação semanal em 30 kg a cada semana seguinte. Em quantas semanas, no mínimo, o total acumulado alcança 1 500 kg?$text$, $text$A soma em n semanas é n[300 + 30(n − 1)]/2 = 15n(n + 9). Em 6 semanas, soma 1 350 kg; em 7, soma 1 680 kg. O mínimo é 7.$text$, 'D', $text$5.$text$, $text$6.$text$, $text$8.$text$, $text$7.$text$, $text$10.$text$),
        ('Q70', 'MATEMATICA', 'Matemática', 'Matemática Financeira', $text$Um equipamento custa R$ 2 000,00 à vista ou pode ser pago com entrada de R$ 800,00 e parcela única de R$ 1 296,00 um mês depois. Qual taxa mensal de juros incide sobre o valor efetivamente financiado?$text$, $text$Após a entrada, o saldo financiado é 2 000 − 800 = 1 200 reais. Os juros são 1 296 − 1 200 = 96 reais. A taxa é 96/1 200 = 0,08 = 8%.$text$, 'E', $text$4,8%.$text$, $text$6%.$text$, $text$12%.$text$, $text$14,8%.$text$, $text$8%.$text$),
        ('Q71', 'MATEMATICA', 'Matemática', 'Análise Combinatória', $text$Uma equipe de 4 pessoas será formada entre 6 estudantes de uma turma e 4 de outra. A equipe deve conter exatamente 2 estudantes de cada turma e não há cargos distintos. Quantas equipes diferentes podem ser formadas?$text$, $text$Escolhem-se 2 entre 6 e 2 entre 4: C(6,2) × C(4,2) = 15 × 6 = 90. Como não há cargos, a ordem dos integrantes não gera uma nova equipe.$text$, 'A', $text$90.$text$, $text$24.$text$, $text$60.$text$, $text$120.$text$, $text$180.$text$),
        ('Q72', 'MATEMATICA', 'Matemática', 'Probabilidade', $text$Em uma fábrica, a linha A produz 60% das peças e tem 2% de defeitos; a linha B produz 40% e tem 5% de defeitos. Uma peça escolhida ao acaso é defeituosa. Qual é a probabilidade de ter vindo da linha B?$text$, $text$A parcela de peças defeituosas de A é 0,60 × 0,02 = 0,012 e a de B é 0,40 × 0,05 = 0,020. Condicionando ao defeito, P(B) = 0,020/0,032 = 0,625.$text$, 'B', $text$20%.$text$, $text$62,5%.$text$, $text$40%.$text$, $text$50%.$text$, $text$71,4%.$text$),
        ('Q73', 'MATEMATICA', 'Matemática', 'Funções', $text$Uma feira vende 100 ingressos a R$ 20,00 cada. Para cada aumento de R$ 2,00 no preço, estima perder 5 compradores. Admitindo que esse modelo seja válido, qual preço maximiza a receita, considerando apenas aumentos em múltiplos de R$ 2,00?$text$, $text$Se x é o número de aumentos, R(x) = (20 + 2x)(100 − 5x) = 2 000 + 100x − 10x². O vértice ocorre em x = 5, valor inteiro admissível. O preço é 20 + 2 × 5 = 30 reais.$text$, 'C', $text$R$ 24,00.$text$, $text$R$ 28,00.$text$, $text$R$ 30,00.$text$, $text$R$ 32,00.$text$, $text$R$ 40,00.$text$),
        ('Q74', 'MATEMATICA', 'Matemática', 'Geometria Analítica', $text$Em um mapa cartesiano, duas unidades de saúde estão em A(2, 2) e B(8, 6), com coordenadas em quilômetros. Um posto P será instalado no eixo horizontal, em P(x, 0), à mesma distância de A e B. Qual é o valor de x?$text$, $text$Igualando os quadrados das distâncias: (x − 2)² + 2² = (x − 8)² + 6². Após simplificar, 12x = 92, logo x = 23/3. Não basta usar a média das abscissas porque as ordenadas são diferentes.$text$, 'D', $text$5.$text$, $text$6.$text$, $text$20/3.$text$, $text$23/3.$text$, $text$8.$text$),
        ('Q75', 'MATEMATICA', 'Matemática', 'Trigonometria', $text$Uma rampa retilínea deve vencer um desnível de 1,5 m. O projeto exige que a razão entre desnível e comprimento horizontal seja, no máximo, 1/12. Qual é o menor comprimento horizontal permitido?$text$, $text$A exigência é 1,5/d ≤ 1/12. Assim, d ≥ 18 m. A razão indicada usa a projeção horizontal, não o comprimento inclinado da rampa.$text$, 'E', $text$12 m.$text$, $text$16,5 m.$text$, $text$18,5 m.$text$, $text$20 m.$text$, $text$18 m.$text$),
        ('Q76', 'MATEMATICA', 'Matemática', 'Estatística', $text$Os tempos, em minutos, de cinco atendimentos foram 8, 9, 10, 11 e 12. Um sexto atendimento demorou 40 minutos. Comparando os conjuntos antes e depois dessa inclusão, qual afirmação é correta?$text$, $text$Antes, média e mediana são 10. Depois, a soma é 90 e a média é 15; a mediana é (10 + 11)/2 = 10,5. O valor extremo afeta mais a média.$text$, 'A', $text$A média aumenta 5 minutos e a mediana aumenta 0,5 minuto.$text$, $text$A média e a mediana aumentam 5 minutos.$text$, $text$A média fica em 10 e a mediana sobe para 15.$text$, $text$A média aumenta 6 minutos e a mediana permanece em 10.$text$, $text$A média e a mediana permanecem iguais por haver apenas um valor novo.$text$),
        ('Q77', 'MATEMATICA', 'Matemática', 'Progressões', $text$Uma cultura tem inicialmente 500 células e dobra a cada 3 horas. Um equipamento deve ser acionado na primeira duplicação em que a população ultrapassar 30 000 células. Após quantas horas ele será acionado?$text$, $text$Após n duplicações, há 500 × 2ⁿ células. É preciso 2ⁿ > 60. Como 2⁵ = 32 e 2⁶ = 64, a primeira duplicação adequada é a sexta, após 18 horas.$text$, 'B', $text$12 horas.$text$, $text$18 horas.$text$, $text$15 horas.$text$, $text$21 horas.$text$, $text$24 horas.$text$),
        ('Q78', 'MATEMATICA', 'Matemática', 'Matemática Financeira', $text$Uma pessoa aplica R$ 5 000,00 a juros compostos de 10% ao ano durante 2 anos. Ao resgatar, paga imposto de 20% apenas sobre o rendimento. Desconsiderando outras cobranças, qual é o valor líquido recebido?$text$, $text$O montante bruto é 5 000 × 1,1² = 6 050 reais. O rendimento é 1 050 e o imposto é 210 reais. O resgate líquido é 6 050 − 210 = 5 840 reais.$text$, 'C', $text$R$ 4 840,00.$text$, $text$R$ 5 800,00.$text$, $text$R$ 5 840,00.$text$, $text$R$ 6 000,00.$text$, $text$R$ 6 050,00.$text$),
        ('Q79', 'MATEMATICA', 'Matemática', 'Geometria Espacial', $text$Uma embalagem cúbica tem aresta interna de 12 cm. Uma nova versão terá todas as dimensões internas ampliadas em 25%. Qual é o aumento percentual de sua capacidade?$text$, $text$A capacidade varia com o cubo do fator linear: 1,25³ = 1,953125. O acréscimo é 0,953125, correspondente a 95,3125%. O aumento do volume não é igual ao da aresta.$text$, 'D', $text$25%.$text$, $text$50%.$text$, $text$56,25%.$text$, $text$95,3125%.$text$, $text$75%.$text$),
        ('Q80', 'MATEMATICA', 'Matemática', 'Razão e Proporção', $text$Uma equipe pode entregar uma obra em 12 dias com 8 trabalhadores de mesma produtividade. Após 3 dias de trabalho, 2 trabalhadores deixam a equipe. Mantidas as jornadas e sem novas contratações, quantos dias serão necessários ao todo?$text$, $text$A obra requer 8 × 12 = 96 trabalhador-dias. Em 3 dias são feitos 24; restam 72. Com 6 trabalhadores, serão mais 12 dias. O total é 3 + 12 = 15 dias.$text$, 'E', $text$12 dias.$text$, $text$14 dias.$text$, $text$16 dias.$text$, $text$18 dias.$text$, $text$15 dias.$text$)
        ) AS seed(code, exam_area, discipline_name, subject_name,
                  statement, explanation, correct_letter,
                  alternative_a, alternative_b, alternative_c, alternative_d, alternative_e)
    LOOP
        SELECT subject.id INTO STRICT subject_uuid
        FROM subjects subject
        JOIN disciplines discipline ON discipline.id = subject.discipline_id
        WHERE subject.name = item.subject_name
          AND discipline.name = item.discipline_name
          AND discipline.exam_area = item.exam_area;

        INSERT INTO questions (id, statement, explanation, subject_id, active, created_at, updated_at)
        VALUES (gen_random_uuid(), item.statement, item.explanation, subject_uuid, TRUE, CURRENT_TIMESTAMP, NULL)
        RETURNING id INTO question_uuid;

        INSERT INTO alternatives (question_id, letter, text, correct)
        VALUES
            (question_uuid, 'A', item.alternative_a, item.correct_letter = 'A'),
            (question_uuid, 'B', item.alternative_b, item.correct_letter = 'B'),
            (question_uuid, 'C', item.alternative_c, item.correct_letter = 'C'),
            (question_uuid, 'D', item.alternative_d, item.correct_letter = 'D'),
            (question_uuid, 'E', item.alternative_e, item.correct_letter = 'E');

        inserted_count := inserted_count + 1;
        area_counts := jsonb_set(area_counts, ARRAY[item.exam_area],
            to_jsonb(COALESCE((area_counts ->> item.exam_area)::INTEGER, 0) + 1));
    END LOOP;

    IF inserted_count <> 80 OR area_counts <>
        '{"LINGUAGENS":20,"CIENCIAS_HUMANAS":20,"CIENCIAS_DA_NATUREZA":20,"MATEMATICA":20}'::JSONB THEN
        RAISE EXCEPTION 'Expected 80 questions, 20 per area; inserted %, distribution %', inserted_count, area_counts;
    END IF;
END
$migration$;
